content:
Save as `index.html` and open it in a modern browser. The scene uses only the Three.js core ES module; camera orbit, pan, zoom, cycle controls, and all geometry are implemented directly in the HTML.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Automated Regolith Sintering Plant</title>

  <style>
    :root {
      color-scheme: dark;
      --panel: rgba(12, 18, 22, 0.82);
      --line: rgba(255, 255, 255, 0.14);
      --text: #edf2f1;
      --muted: #9eaaa9;
      --accent: #f2a23a;
      --cyan: #73d4d0;
    }

    * {
      box-sizing: border-box;
    }

    html,
    body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      background: #89999f;
      font-family:
        Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
        "Segoe UI", sans-serif;
    }

    #scene {
      position: fixed;
      inset: 0;
    }

    #scene canvas {
      display: block;
      width: 100%;
      height: 100%;
      touch-action: none;
    }

    #hud {
      position: fixed;
      inset: 0;
      pointer-events: none;
    }

    .panel {
      background: var(--panel);
      border: 1px solid var(--line);
      border-radius: 12px;
      box-shadow: 0 16px 50px rgba(0, 0, 0, 0.25);
      backdrop-filter: blur(14px);
      -webkit-backdrop-filter: blur(14px);
    }

    .brand {
      position: absolute;
      top: 20px;
      left: 20px;
      width: min(430px, calc(100vw - 40px));
      padding: 17px 19px 16px;
    }

    .eyebrow {
      color: var(--accent);
      font-size: 10px;
      font-weight: 800;
      letter-spacing: 0.2em;
      text-transform: uppercase;
    }

    h1 {
      margin: 7px 0 5px;
      font-size: clamp(20px, 2.2vw, 31px);
      line-height: 1.05;
      letter-spacing: -0.035em;
    }

    .subtitle {
      margin: 0;
      color: var(--muted);
      font-size: 12px;
      line-height: 1.5;
    }

    .telemetry {
      position: absolute;
      top: 20px;
      right: 20px;
      width: 270px;
      padding: 15px 16px;
    }

    .telemetry-row {
      display: flex;
      justify-content: space-between;
      gap: 12px;
      margin: 8px 0;
      color: var(--muted);
      font-size: 11px;
    }

    .telemetry-row strong {
      color: var(--text);
      font-size: 11px;
      font-variant-numeric: tabular-nums;
    }

    #phaseText {
      margin-top: 13px;
      padding-top: 12px;
      border-top: 1px solid var(--line);
      color: var(--accent);
      font-size: 11px;
      font-weight: 800;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .progress-track {
      height: 4px;
      margin-top: 10px;
      overflow: hidden;
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.1);
    }

    #progressFill {
      width: 0;
      height: 100%;
      background: linear-gradient(90deg, var(--accent), #ffd079);
      box-shadow: 0 0 12px rgba(242, 162, 58, 0.6);
    }

    .process {
      position: absolute;
      left: 20px;
      bottom: 20px;
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 12px 15px;
      color: var(--muted);
      font-size: 10px;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .process span {
      color: var(--text);
    }

    .process .arrow {
      color: var(--accent);
      font-size: 14px;
    }

    .controls {
      position: absolute;
      right: 20px;
      bottom: 20px;
      display: flex;
      flex-wrap: wrap;
      justify-content: flex-end;
      gap: 7px;
      pointer-events: auto;
    }

    button {
      appearance: none;
      border: 1px solid var(--line);
      border-radius: 8px;
      padding: 9px 12px;
      background: rgba(255, 255, 255, 0.055);
      color: var(--text);
      font: inherit;
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 0.035em;
      cursor: pointer;
      transition:
        background 150ms ease,
        border-color 150ms ease,
        transform 150ms ease;
    }

    button:hover {
      background: rgba(255, 255, 255, 0.12);
      border-color: rgba(255, 255, 255, 0.28);
    }

    button:active {
      transform: translateY(1px);
    }

    button.primary {
      color: #17130a;
      background: var(--accent);
      border-color: var(--accent);
    }

    button.primary:hover {
      background: #ffc068;
    }

    .hint {
      position: absolute;
      left: 50%;
      bottom: 22px;
      transform: translateX(-50%);
      padding: 8px 12px;
      color: rgba(255, 255, 255, 0.76);
      font-size: 10px;
      letter-spacing: 0.04em;
      white-space: nowrap;
    }

    #loading {
      position: fixed;
      inset: 0;
      z-index: 20;
      display: grid;
      place-items: center;
      background: #11181c;
      color: var(--text);
      transition: opacity 500ms ease;
    }

    #loading.hide {
      opacity: 0;
      pointer-events: none;
    }

    .loader {
      width: 220px;
      text-align: center;
    }

    .loader-bar {
      height: 3px;
      margin-top: 14px;
      overflow: hidden;
      background: rgba(255, 255, 255, 0.1);
    }

    .loader-bar::after {
      content: "";
      display: block;
      width: 45%;
      height: 100%;
      background: var(--accent);
      animation: load 1.1s ease-in-out infinite;
    }

    @keyframes load {
      from {
        transform: translateX(-10%);
      }
      to {
        transform: translateX(135%);
      }
    }

    @media (max-width: 760px) {
      .brand {
        top: 12px;
        left: 12px;
        width: calc(100vw - 24px);
      }

      .telemetry {
        top: 122px;
        right: 12px;
        width: 210px;
      }

      .process {
        left: 12px;
        bottom: 76px;
      }

      .controls {
        right: 12px;
        bottom: 12px;
        left: 12px;
        justify-content: center;
      }

      .hint {
        display: none;
      }
    }
  </style>
</head>

<body>
  <div id="scene"></div>

  <div id="hud">
    <section class="brand panel">
      <div class="eyebrow">Lunar Infrastructure / Station 07</div>
      <h1>Automated Regolith Sintering Plant</h1>
      <p class="subtitle">
        Rail-mounted kiln cars, hydraulic pressing gantry, elevated bucket
        elevator, and continuous tunnel sintering.
      </p>
    </section>

    <section class="telemetry panel">
      <div class="telemetry-row">
        <span>Plant status</span>
        <strong id="plantStatus">AUTOMATED</strong>
      </div>
      <div class="telemetry-row">
        <span>Active car</span>
        <strong id="carNumber">01 / 03</strong>
      </div>
      <div class="telemetry-row">
        <span>Press cycles</span>
        <strong id="pressCount">000</strong>
      </div>
      <div class="telemetry-row">
        <span>Cycle</span>
        <strong id="cycleNumber">01</strong>
      </div>
      <div id="phaseText">Loading car 01</div>
      <div class="progress-track">
        <div id="progressFill"></div>
      </div>
    </section>

    <section class="process panel">
      <span>Elevator</span><i class="arrow">→</i>
      <span>Hopper</span><i class="arrow">→</i>
      <span>Press</span><i class="arrow">→</i>
      <span>Sinter</span>
    </section>

    <nav class="controls panel" aria-label="Scene controls">
      <button id="pauseButton" class="primary">Pause</button>
      <button data-preset="overview">Overview</button>
      <button data-preset="gantry">Gantry</button>
      <button data-preset="kiln">Kiln</button>
      <button id="resetButton">Restart Cycle</button>
    </nav>

    <div class="hint panel">
      Drag to orbit · Shift/right-drag to pan · Scroll to zoom · Double-click for overview
    </div>
  </div>

  <div id="loading">
    <div class="loader">
      <div class="eyebrow">Initializing plant systems</div>
      <div class="loader-bar"></div>
    </div>
  </div>

  <script type="module">
    import * as THREE from
      "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    // -------------------------------------------------------------------------
    // Renderer and scene
    // -------------------------------------------------------------------------

    const sceneHost = document.getElementById("scene");

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: true,
      powerPreference: "high-performance"
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.12;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.setClearColor(0x89999f, 0);
    sceneHost.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    scene.fog = new THREE.Fog(0x92a1a5, 48, 115);

    const camera = new THREE.PerspectiveCamera(
      43,
      window.innerWidth / window.innerHeight,
      0.1,
      180
    );

    const hemi = new THREE.HemisphereLight(0xc5d8df, 0x4b3829, 2.0);
    scene.add(hemi);

    const sun = new THREE.DirectionalLight(0xfff1d2, 3.4);
    sun.position.set(18, 30, 22);
    sun.castShadow = true;
    sun.shadow.mapSize.set(2048, 2048);
    sun.shadow.camera.left = -42;
    sun.shadow.camera.right = 42;
    sun.shadow.camera.top = 30;
    sun.shadow.camera.bottom = -30;
    sun.shadow.camera.near = 1;
    sun.shadow.camera.far = 90;
    sun.shadow.bias = -0.00025;
    scene.add(sun);

    const rimLight = new THREE.DirectionalLight(0x8bc9db, 1.2);
    rimLight.position.set(-25, 15, -24);
    scene.add(rimLight);

    // -------------------------------------------------------------------------
    // Utilities and materials
    // -------------------------------------------------------------------------

    let seed = 7319;

    function random() {
      seed = (seed * 1664525 + 1013904223) >>> 0;
      return seed / 4294967296;
    }

    function range(min, max) {
      return min + (max - min) * random();
    }

    function addMesh(
      geometry,
      material,
      position = [0, 0, 0],
      parent = scene
    ) {
      const mesh = new THREE.Mesh(geometry, material);
      mesh.position.set(...position);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function box(
      width,
      height,
      depth,
      material,
      x = 0,
      y = 0,
      z = 0,
      parent = scene
    ) {
      return addMesh(
        new THREE.BoxGeometry(width, height, depth),
        material,
        [x, y, z],
        parent
      );
    }

    function cylinder(
      radiusTop,
      radiusBottom,
      height,
      material,
      x = 0,
      y = 0,
      z = 0,
      parent = scene,
      segments = 16
    ) {
      return addMesh(
        new THREE.CylinderGeometry(
          radiusTop,
          radiusBottom,
          height,
          segments
        ),
        material,
        [x, y, z],
        parent
      );
    }

    function beamBetween(a, b, radius, material, parent = scene) {
      const start = new THREE.Vector3(...a);
      const end = new THREE.Vector3(...b);
      const direction = end.clone().sub(start);
      const length = direction.length();

      const mesh = addMesh(
        new THREE.CylinderGeometry(radius, radius, length, 8),
        material,
        start.clone().add(end).multiplyScalar(0.5).toArray(),
        parent
      );

      mesh.quaternion.setFromUnitVectors(
        new THREE.Vector3(0, 1, 0),
        direction.normalize()
      );

      return mesh;
    }

    function makeTexture(canvas) {
      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.wrapS = THREE.RepeatWrapping;
      texture.wrapT = THREE.RepeatWrapping;
      texture.anisotropy = renderer.capabilities.getMaxAnisotropy();
      return texture;
    }

    const regolithCanvas = document.createElement("canvas");
    regolithCanvas.width = 256;
    regolithCanvas.height = 256;
    const regolithContext = regolithCanvas.getContext("2d");

    regolithContext.fillStyle = "#715b45";
    regolithContext.fillRect(0, 0, 256, 256);

    for (let i = 0; i < 2400; i++) {
      const shade = Math.floor(range(65, 145));
      regolithContext.fillStyle = `rgba(${shade}, ${Math.floor(shade * 0.75)}, ${Math.floor(shade * 0.55)}, ${range(0.08, 0.35)})`;
      const size = range(1, 5);
      regolithContext.fillRect(
        random() * 256,
        random() * 256,
        size,
        size
      );
    }

    const regolithTexture = makeTexture(regolithCanvas);
    regolithTexture.repeat.set(10, 6);

    const materials = {
      ground: new THREE.MeshStandardMaterial({
        color: 0x76624c,
        map: regolithTexture,
        roughness: 1
      }),
      regolith: new THREE.MeshStandardMaterial({
        color: 0x82694f,
        map: regolithTexture,
        bumpMap: regolithTexture,
        bumpScale: 0.22,
        roughness: 0.98
      }),
      ballast: new THREE.MeshStandardMaterial({
        color: 0x4b4035,
        roughness: 1
      }),
      steel: new THREE.MeshStandardMaterial({
        color: 0x596266,
        metalness: 0.72,
        roughness: 0.43
      }),
      darkSteel: new THREE.MeshStandardMaterial({
        color: 0x252d30,
        metalness: 0.68,
        roughness: 0.5
      }),
      black: new THREE.MeshStandardMaterial({
        color: 0x101416,
        metalness: 0.45,
        roughness: 0.62
      }),
      yellow: new THREE.MeshStandardMaterial({
        color: 0xd59a2c,
        metalness: 0.48,
        roughness: 0.42
      }),
      orange: new THREE.MeshStandardMaterial({
        color: 0xd96824,
        metalness: 0.4,
        roughness: 0.48
      }),
      red: new THREE.MeshStandardMaterial({
        color: 0x9d2d25,
        metalness: 0.35,
        roughness: 0.5
      }),
      glass: new THREE.MeshStandardMaterial({
        color: 0x18313a,
        metalness: 0.55,
        roughness: 0.18
      }),
      glow: new THREE.MeshBasicMaterial({
        color: 0xff641d,
        toneMapped: false
      }),
      kilnGlow: new THREE.MeshBasicMaterial({
        color: 0x3d1006,
        side: THREE.DoubleSide,
        toneMapped: false
      }),
      white: new THREE.MeshStandardMaterial({
        color: 0xd8ddd8,
        metalness: 0.25,
        roughness: 0.5
      })
    };

    // -------------------------------------------------------------------------
    // Terrain, track, and distant landscape
    // -------------------------------------------------------------------------

    const ground = addMesh(
      new THREE.PlaneGeometry(72, 36),
      materials.ground,
      [0, -0.08, 0]
    );
    ground.rotation.x = -Math.PI / 2;
    ground.castShadow = false;

    box(62, 0.25, 4.8, materials.ballast, 0, 0.02, 0);

    for (let x = -30; x <= 30; x += 1.15) {
      box(0.28, 0.18, 3.65, materials.ballast, x, 0.18, 0);
    }

    for (const z of [-1.16, 1.16]) {
      box(62, 0.18, 0.13, materials.steel, 0, 0.34, z);
    }

    for (const z of [-3.46, 3.46]) {
      box(54, 0.16, 0.16, materials.steel, 0, 0.32, z);
    }

    for (let i = 0; i < 28; i++) {
      const rock = addMesh(
        new THREE.IcosahedronGeometry(range(0.35, 1.5), 0),
        materials.regolith,
        [
          range(-34, 34),
          range(0.1, 0.7),
          range(-10, 10)
        ]
      );
      rock.scale.y = range(0.45, 1.2);
      rock.rotation.set(range(), range(), range());
    }

    for (let i = 0; i < 9; i++) {
      const mesa = addMesh(
        new THREE.CylinderGeometry(
          range(5, 9),
          range(9, 15),
          range(5, 10),
          6
        ),
        materials.regolith,
        [
          range(-42, 42),
          range(2.5, 5),
          range(-20, 18)
        ]
      );
      mesa.rotation.y = range(0, Math.PI);
      mesa.scale.z = range(0.65, 1.2);
    }

    // -------------------------------------------------------------------------
    // Long tunnel kiln
    // -------------------------------------------------------------------------

    const kiln = new THREE.Group();
    scene.add(kiln);

    function createArchShell(x0, x1, radius, baseY, material) {
      const arcSegments = 30;
      const positions = [];
      const indices = [];

      for (let i = 0; i <= 4; i++) {
        const t = i / 4;
        const x = THREE.MathUtils.lerp(x0, x1, t);

        for (let j = 0; j <= arcSegments; j++) {
          const angle = (j / arcSegments) * Math.PI;
          positions.push(
            x,
            baseY + radius * Math.sin(angle),
            radius * Math.cos(angle)
          );
        }
      }

      for (let i = 0; i < 4; i++) {
        for (let j = 0; j < arcSegments; j++) {
          const a = i * (arcSegments + 1) + j;
          const b = (i + 1) * (arcSegments + 1) + j;
          const c = b + 1;
          const d = a + 1;
          indices.push(a, b, d, b, c, d);
        }
      }

      const geometry = new THREE.BufferGeometry();
      geometry.setAttribute(
        "position",
        new THREE.Float32BufferAttribute(positions, 3)
      );
      geometry.setIndex(indices);
      geometry.computeVertexNormals();

      return new THREE.Mesh(geometry, material);
    }

    const kilnShell = createArchShell(
      11.5,
      33.5,
      4.15,
      4.15,
      materials.darkSteel
    );
    kilnShell.material.side = THREE.DoubleSide;
    kiln.add(kilnShell);

    const kilnInterior = createArchShell(
      11.65,
      33.35,
      3.72,
      4.15,
      materials.black
    );
    kilnInterior.material.side = THREE.BackSide;
    kiln.add(kilnInterior);

    box(22, 0.22, 7.2, materials.darkSteel, 22.5, 0.35, 0, kiln);

    for (const z of [-2.55, 2.55]) {
      const strip = box(
        22,
        0.08,
        0.09,
        materials.glow,
        22.5,
        0.52,
        z,
        kiln
      );
      strip.castShadow = false;
    }

    for (const x of [11.5, 33.5]) {
      const points = [];

      for (let i = 0; i <= 18; i++) {
        const angle = (i / 18) * Math.PI;
        points.push(
          new THREE.Vector3(
            x,
            4.15 + 4.15 * Math.sin(angle),
            4.15 * Math.cos(angle)
          )
        );
      }

      const curve = new THREE.CatmullRomCurve3(points);
      addMesh(
        new THREE.TubeGeometry(curve, 36, 0.17, 7, false),
        materials.steel,
        [0, 0, 0],
        kiln
      );
    }

    for (let x = 13; x <= 31; x += 6.5) {
      for (const z of [-3.15, 3.15]) {
        box(0.38, 3.8, 0.38, materials.steel, x, 2.05, z, kiln);
      }
      beamBetween(
        [x, 0.5, -3.1],
        [x, 3.8, 3.1],
        0.09,
        materials.darkSteel,
        kiln
      );
    }

    for (const x of [15, 22, 29]) {
      const light = new THREE.PointLight(0xff641f, 42, 15, 2);
      light.position.set(x, 4.3, 0);
      kiln.add(light);

      box(
        0.22,
        0.12,
        5.4,
        materials.glow,
        x + 0.08,
        0.67,
        0,
        kiln
      ).castShadow = false;
    }

    const opening = addMesh(
      new THREE.CircleGeometry(3.75, 36, 0, Math.PI),
      materials.kilnGlow,
      [33.52, 4.15, 0],
      kiln
    );
    opening.rotation.y = Math.PI / 2;
    opening.castShadow = false;

    // -------------------------------------------------------------------------
    // Rail-mounted kiln car train
    // -------------------------------------------------------------------------

    const train = new THREE.Group();
    scene.add(train);

    function createKilnCar(x, carIndex) {
      const car = new THREE.Group();
      car.position.x = x;
      train.add(car);

      box(7.1, 2.25, 3.15, materials.steel, 0, 1.65, 0, car);
      box(7.35, 0.24, 3.45, materials.darkSteel, 0, 2.9, 0, car);
      box(6.9, 0.25, 3.25, materials.orange, 0, 0.75, 0, car);

      for (const z of [-1.61, 1.61]) {
        for (let rib = -2.7; rib <= 2.7; rib += 1.35) {
          box(0.12, 1.75, 0.1, materials.darkSteel, rib, 1.65, z, car);
        }

        for (let windowIndex = -2; windowIndex <= 2; windowIndex++) {
          box(
            0.72,
            0.48,
            0.06,
            materials.glass,
            windowIndex * 1.05,
            2.35,
            z,
            car
          );
        }
      }

      for (const wheelX of [-2.25, 2.25]) {
        for (const wheelZ of [-1.27, 1.27]) {
          const wheel = cylinder(
            0.43,
            0.43,
            0.3,
            materials.black,
            wheelX,
            0.48,
            wheelZ,
            car,
            18
          );
          wheel.rotation.x = Math.PI / 2;

          const hub = cylinder(
            0.19,
            0.19,
            0.33,
            materials.steel,
            wheelX,
            0.48,
            wheelZ,
            car,
            14
          );
          hub.rotation.x = Math.PI / 2;
        }

        box(1.25, 0.3, 2.7, materials.darkSteel, wheelX, 0.7, 0, car);
      }

      for (const z of [-1.05, 1.05]) {
        box(0.16, 2.1, 0.16, materials.steel, 0, 1.6, z, car);
      }

      const numberCanvas = document.createElement("canvas");
      numberCanvas.width = 128;
      numberCanvas.height = 96;
      const numberContext = numberCanvas.getContext("2d");
      numberContext.fillStyle = "#172024";
      numberContext.fillRect(0, 0, 128, 96);
      numberContext.strokeStyle = "#d59a2c";
      numberContext.lineWidth = 8;
      numberContext.strokeRect(7, 7, 114, 82);
      numberContext.fillStyle = "#f1eee3";
      numberContext.font = "bold 54px sans-serif";
      numberContext.textAlign = "center";
      numberContext.textBaseline = "middle";
      numberContext.fillText(`KC-${String(carIndex + 1).padStart(2, "0")}`, 64, 50);

      const numberTexture = new THREE.CanvasTexture(numberCanvas);
      numberTexture.colorSpace = THREE.SRGBColorSpace;

      const numberSprite = new THREE.Sprite(
        new THREE.SpriteMaterial({
          map: numberTexture,
          transparent: true,
          depthWrite: false
        })
      );
      numberSprite.scale.set(2.25, 1.7, 1);
      numberSprite.position.set(0, 3.35, 1.78);
      car.add(numberSprite);

      const statusLight = addMesh(
