    const cameraTarget = new THREE.Vector3(3, 3.2, 0);
    const cameraTargetGoal = new THREE.Vector3(3, 3.2, 0);
    let cameraYaw = 0.67;
    let cameraPitch = 0.52;
    let cameraDistance = 55;
    let cameraGoal = null;

    const presets = {
      overview: {
        target: [3, 3.2, 0],
        yaw: 0.67,
        pitch: 0.52,
        distance: 55
      },
      gantry: {
        target: [-2, 4.4, 0],
