    function setCameraPreset(name) {
      const preset = presets[name];
      cameraTargetGoal.set(...preset.target);
      cameraTargetGoal.y = THREE.MathUtils.clamp(
        cameraTargetGoal.y,
        0.5,
        13
      );

      let angleDifference =
        Math.atan2(
          Math.sin(preset.yaw - cameraYaw),
          Math.cos(preset.yaw - cameraYaw)
        );

      cameraYawGoal = cameraYaw + angleDifference;
      cameraPitchGoal = preset.pitch;
      cameraDistanceGoal = preset.distance;
      cameraGoal = true;
    }

    function updateCamera(dt) {
      if (cameraGoal) {
        const blend = 1 - Math.exp(-dt * 2.2);

        cameraTarget.lerp(cameraTargetGoal, blend);
        cameraYaw +=
          (cameraYawGoal - cameraYaw) * (1 - Math.exp(-dt * 4));
        cameraPitch +=
          (cameraPitchGoal - cameraPitch) * (1 - Math.exp(-dt * 4));
        cameraDistance +=
          (cameraDistanceGoal - cameraDistance) * (1 - Math.exp(-dt * 4));

        if (
          cameraTarget.distanceTo(cameraTargetGoal) < 0.02 &&
          Math.abs(cameraYaw - cameraYawGoal) < 0.001 &&
          Math.abs(cameraPitch - cameraPitchGoal) < 0.001 &&
          Math.abs(cameraDistance - cameraDistanceGoal) < 0.02
        ) {
          cameraGoal = false;
        }
      }

      const horizontal = Math.cos(cameraPitch) * cameraDistance;

      camera.position.set(
        cameraTarget.x + Math.sin(cameraYaw) * horizontal,
        cameraTarget.y + Math.sin(cameraPitch) * cameraDistance,
        cameraTarget.z + Math.cos(cameraYaw) * horizontal
      );

      camera.lookAt(cameraTarget);
    }

    const canvas = renderer.domElement;
