    canvas.addEventListener("pointermove", (event) => {
      if (!drag) return;

      const dx = event.clientX - drag.x;
      const dy = event.clientY - drag.y;
      drag.x = event.clientX;
      drag.y = event.clientY;

      if (drag.pan) {
        const right = new THREE.Vector3().setFromMatrixColumn(
          camera.matrix,
          0
        );
        const up = new THREE.Vector3().setFromMatrixColumn(
          camera.matrix,
          1
        );
        const panScale = cameraDistance * 0.0013;

        cameraTarget.addScaledVector(right, -dx * panScale);
        cameraTarget.addScaledVector(up, dy * panScale);

        cameraTarget.x = THREE.MathUtils.clamp(
          cameraTarget.x,
          -35,
          38
        );
        cameraTarget.y = THREE.MathUtils.clamp(
          cameraTarget.y,
          0.5,
          13
        );
        cameraTarget.z = THREE.MathUtils.clamp(
