    let paused = false;

    const phaseDurations = [1.5, 1.2, 1.4, 1.2, 3.2];
    const phaseNames = [
      "Locating car",
      "Lowering press",
      "Sintering press",
      "Raising press",
      "Traversing gantry"
    ];

