    function easeInOutCubic(value) {
      return value < 0.5
        ? 4 * value * value * value
        : 1 - Math.pow(-2 * value + 2, 3) / 2;
    }

    function smoothstep(value) {
      return value * value * (3 - 2 * value);
    }

    function resetCycle() {
      cycleIndex = 0;
      phase = 1;
      phaseTime = 0;
      pressCount = 0;
      simulationTime = 0;

      gantry.position.x = carXs[0];
      trolley.position.z = 0;
      pressHead.position.y = 3.95;
      pressHead.position.x = 0;

      const pistonBottom = 3.95 + 0.25;
      const pistonTop = 5.45;
      ramPiston.scale.y = 1;
      ramPiston.position.y = (pistonBottom + pistonTop) * 0.5;

      didPressThisCycle = false;
      updateUi();
    }

    let didPressThisCycle = false;

    function updateCycle(dt) {
      if (phase === 3 && !didPressThisCycle) {
        pressCount++;
        didPressThisCycle = true;
      }

      let targetX = carXs[cycleIndex];
      let targetZ = 0;
      let headTarget = 3.95;

      if (phase === 5) {
        targetX = carXs[(cycleIndex + 1) % carXs.length];
      }

      let eased;

      if (phase < 5) {
        eased = smoothstep(phaseTime / phaseDurations[phase]);
      } else {
        eased = smoothstep((phaseTime - phaseDurations[0] - phaseDurations[1] - phaseDurations[2] - phaseDurations[3]) / phaseDurations[4]);
      }

      gantry.position.x = THREE.MathUtils.lerp(
        gantry.position.x,
        targetX,
        eased
      );

      trolley.position.z = THREE.MathUtils.lerp(
        trolley.position.z,
        targetZ,
        eased
      );

      if (phase >= 2) {
        headTarget = 2.95;
      }

      pressHead.position.y = THREE.MathUtils.lerp(
        pressHead.position.y,
        headTarget,
        eased
      );

      if (phase === 3) {
        pressHead.position.x = Math.sin(simulationTime * 32) * 0.025;
        pressHeadMat.emissiveIntensity =
          1.2 + Math.sin(simulationTime * 24) * 0.35;
        contactLight.intensity = 8 + Math.sin(simulationTime * 31) * 3;
      } else {
        pressHeadMat.emissiveIntensity = 0.18;
        contactLight.intensity = 0;
      }

      const pistonBottom = pressHead.position.y + 0.25;
      const pistonTop = 5.45;
      const pistonLength = Math.max(0.35, pistonTop - pistonBottom);

      ramPiston.scale.y = pistonLength;
      ramPiston.position.y =
        (pistonTop + pistonBottom) * 0.5;

      if (phase === 4 && phaseTime >= phaseDurations[3]) {
        phase = 5;
        phaseTime = 0;
      }

      if (phase === 5 && phaseTime >= phaseDurations[4]) {
        cycleIndex = (cycleIndex + 1) % carXs.length;
        phase = 1;
        phaseTime = 0;
      }

      updateUi();
    }

    // -------------------------------------------------------------------------
    // UI and animation loop
    // -------------------------------------------------------------------------

    function updateUi() {
      const carIndex = carPositions.indexOf(carXs[cycleIndex]);
      carNumber.textContent =
        `${String(carIndex + 1).padStart(2, "0")} / 03`;

      pressCountElement.textContent = String(pressCount).padStart(4, "0");
      cycleNumber.textContent = String(cycleIndex + 1).padStart(2, "0");

      phaseText.textContent = phaseNames[phase];
      phaseText.style.color = phase === 3 ? "#ffbd66" : "#f2a23a";

      let progress;

      if (phase < 5) {
        progress =
          (cycleIndex + (phase - 1) / 5) / (carPositions.length - 1);
      } else {
        progress =
          (cycleIndex + 1) / carPositions.length;
      }

      progressFill.style.width = `${THREE.MathUtils.clamp(
        progress,
        0,
        1
      ) * 100}%`;
    }

    pauseButton.addEventListener("click", () => {
      paused = !paused;
      pauseButton.textContent = paused ? "Resume" : "Pause";
      pauseButton.classList.toggle("primary", !paused);
      plantStatus.textContent = paused ? "PAUSED" : "AUTOMATED";
    });

    resetButton.addEventListener("click", resetCycle);

    document.querySelectorAll("[data-preset]").forEach((button) => {
