        setCameraPreset(button.dataset.preset);
      });
    });

    const pressHeadMaterial = materials.orange.clone();

    resetCycle();
    updateCamera(1);

    const clock = new THREE.Clock();

    function animate() {
      const dt = Math.min(clock.getDelta(), 0.05);

      if (!paused) {
        simulationTime += dt;
      }

      updateCycle(dt);

      // Conveyor slats move along the feed line.
      beltSlats.forEach((slat, i) => {
        const travel = (simulationTime * 1.15 + i * 0.85) % 16;
        slat.position.x = -19 + travel;
      });

      // Elevator buckets ascend the tower and loop at the top.
      buckets.forEach((bucket, i) => {
        const travel = (simulationTime * 1.1 + i * 1.12) % 10.2;
        bucket.position.y = 1.25 + travel;
        bucket.rotation.y = simulationTime * 0.35 + i * 0.7;
      });

      // Regolith falls from the fixed hopper into the traveling gantry.
      fallingChunks.forEach((chunk, i) => {
        const t = (simulationTime * 0.38 + chunk.offset) % 1;
        chunk.mesh.position.x = THREE.MathUtils.lerp(-4, gantry.position.x, t);
        chunk.mesh.position.y = THREE.MathUtils.lerp(11.25, 9.35, t);
        chunk.mesh.position.z =
          chunk.z + Math.sin(simulationTime * 2 + i) * 0.16;
        chunk.mesh.rotation.x += dt * 1.4;
        chunk.mesh.rotation.z += dt * 1.1;
      });

      // Suspended dust drifts down through the plant.
      const positionAttribute = dustGeometry.getAttribute("position");

      for (let i = 0; i < dustCount; i++) {
        let y = positionAttribute.getY(i) - dustSpeeds[i] * dt;
        let x = positionAttribute.getX(i) +
          Math.sin(simulationTime * 0.6 + i) * dt * 0.08;

        if (y < 0.1) {
          y = range(10, 12);
          x = range(-30, 32);
        }

        positionAttribute.setY(i, y);
        positionAttribute.setX(i, x);
      }

      positionAttribute.needsUpdate = true;

      // Subtle kiln heat pulsation.
      for (const light of [
        scene.children.find((object) => object.isPointLight),
        ...[1, 2, 3].map(() => scene.children.find(
          (object) => object.isPointLight && object.position.x > 15
        ))
      ]) {
        if (light) {
          light.intensity = 40 + Math.sin(simulationTime * 1.8) * 4;
        }
      }

      updateCamera(dt);
      renderer.render(scene, camera);
    }

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });

    renderer.setAnimationLoop(animate);

    requestAnimationFrame(() => {
      document.getElementById("loading").classList.add("hide");
    });
  </script>
